import type { Metadata } from "next";
import { Outfit, Instrument_Sans } from "next/font/google";
import "./globals.css";

const outfit = Outfit({
    subsets: ["latin"],
    variable: "--font-outfit"
});

const instrumentSans = Instrument_Sans({
    subsets: ["latin"],
    variable: "--font-instrument"
});

export const metadata: Metadata = {
    title: "Manobala MVJ | Product Designer",
    description: "UI/UX Designer and Product Designer Portfolio",
};

export default function RootLayout({
    children,
}: Readonly<{
    children: React.ReactNode;
}>) {
    return (
        <html lang="en" className="scroll-smooth" suppressHydrationWarning>
            <body className={`${outfit.variable} ${instrumentSans.variable} font-sans antialiased bg-[#0B0F14] text-white selection:bg-[#1A7AFF]/30`} suppressHydrationWarning>
                {children}
            </body>
        </html>
    );
}
